<script setup>
import {computed,ref} from 'vue';import {useTimeline} from './useTimeline';import {DURATION,INCIDENT,binsFor,clock} from './data';import LanePlot from './LanePlot.vue';import TimeAxis from './TimeAxis.vue';
const {state,filtered,inspect}=useTimeline();const focus=computed({get:()=>state.lensStart,set:v=>state.lensStart=v});const width=300;
const bins=computed(()=>binsFor(filtered.value,0,DURATION,96));const max=computed(()=>Math.max(1,...bins.value.map(b=>b.count)));
function locate(b){focus.value=Math.min(DURATION-width,Math.max(0,(b.start+b.end)/2-width/2))}
function move(delta){focus.value=Math.max(0,Math.min(DURATION-width,focus.value+delta))}
</script><template><div class="lens-context"><div class="section-caption"><b>כל היום · 16 שעות</b><span>הקשר קבוע, ללא תלות בזום הכללי</span></div><div class="context-bars" dir="ltr"><button v-for="b in bins" :key="b.start" :class="{alert:b.alert}" :style="{height:Math.max(4,b.count/max*46)+'px'}" :title="clock(b.start)+' · פתיחת עדשה'" @click="locate(b)"></button><i class="lens-marker" :style="{left:focus/DURATION*100+'%',width:width/DURATION*100+'%'}"></i></div><TimeAxis :start="0" :end="DURATION"/></div><div class="lens-bridge"><span></span><b>×192 הגדלה · 5 דקות</b><span></span></div><div class="lens-detail"><div class="section-caption"><b dir="ltr">{{clock(focus)}} — {{clock(focus+width)}}</b><div><button @click="move(-150)">← 2.5 דק׳</button><button @click="focus=INCIDENT-60">חלון האירוע</button><button @click="move(150)">2.5 דק׳ →</button><button @click="inspect(focus,focus+width)">רשומות העדשה ↗</button></div></div><LanePlot :start="focus" :end="focus+width" compact/></div></template>